const navigationVerticalSizing = navigationVerticalSizingDrill();
if (!navigationVerticalSizing.endsWith('keep the margin wrapper')) {
  console.error(`✗ NavigationBar vertical sizing drill: ${navigationVerticalSizing}`);
  process.exit(1);
}
console.log(`NavigationBar vertical sizing drill: ${navigationVerticalSizing}.`);

// ─── NavigationBarItem: the bare-label pose and the selection mark ──────────
//
// `Show icon` drops the glyph of a member that also has a label — the
// bare-label tab `CoreNavigationBarItem.destination(icon: null, label: …)`
// draws; an icon-only member keeps its glyph. `Show mark` is the bar's
// `CoreNavigationSelectionMark.dot`: a `Badge` dot over the content of every
// member that stacks its label with its icon (`marksAt` — a row has no top),
