    const row = named(member, 'item')[0];
    if (!row) return `${member.name} has no item`;
    const marks = named(member, 'selection mark');
    const anchor = named(member, 'iconAnchor')[0];
    if (member.name.includes('Label=end')) {
      if (marks.length !== 0) return `${member.name} draws a selection mark — a row has no top to put it on`;
      const glyph = row.children.find((c) => c.name === 'content')?.children[0];
      if (refsOf(glyph).visible !== showIcon[0]) {
        return `${member.name}'s glyph is not behind Show icon`;
      }
      continue;
    }
    if (marks.length !== 1) return `${member.name} draws ${marks.length} selection mark(s), not one`;
    const dot = marks[0];
