    const face = (label as unknown as { fontName?: { style?: string } | null }).fontName?.style;
    if (face !== weightStyle(wantWeight)) {
      return `${size} label draws the ${String(face)} face, not the size row's ${weightStyle(wantWeight)} — the row's \`labelStyle.fontWeight\` is not being read`;
    }
