      // The member's OWN pair — direct children: the close button's instance
      // carries a ring of its own, at the Button's corner. A pill's pair stays
      // a pill: anything at or past the face's own corner is still a half circle.
      const ring = rest.children.find((n) => n.type === 'FRAME' && n.name === 'focus ring') as Geo | undefined;
      const band = rest.children.find((n) => n.type === 'RECTANGLE' && n.name === 'focus offset') as Geo | undefined;
      if (!ring || !band) return `${size} ${shape} member draws no focus ring / offset band to read the corner from`;
