      const effective = own ?? (main == null ? undefined : radiusOf(main));
      if (typeof effective !== 'number') return `${size} ${shape} close button has no corner to compare (override ${String(own)})`;
      if (effective > face) {
        return `${size} ${shape} close button corner ${effective} is rounder than the chip face ${face} that holds it`;
      }
      const stated = rows[size]?.closeButtonStyle?.borderRadius?.topLeft?.v;
